INSERT INTO service_app (id, replicas) VALUES ('payment-service', 4);
INSERT INTO config_key (key_name, service_id, current_value, description) VALUES
  ('spring.datasource.hikari.maximum-pool-size', 'payment-service', '20', 'Connections per replica. 4 replicas x pool size must stay under MySQL max_connections (150).'),
  ('spring.datasource.hikari.connection-timeout', 'payment-service', '30000', 'Milliseconds to wait for a pooled connection. Lower values caused errors at peak (INC-31).'),
  ('payment.retry.max-attempts', 'payment-service', '3', 'Gateway retry attempts. Above 3 requires idempotency (ADR-9).'),
  ('payment.retry.idempotency-enabled', 'payment-service', 'true', 'Idempotency keys on gateway calls. Makes retries safe.'),
  ('payment.gateway.timeout-ms', 'payment-service', '8000', 'Gateway call timeout in ms. Longer values piled up threads in a provider outage (INC-24).'),
  ('payment.settlement.cron', 'payment-service', '0 30 1 * * *', 'Month-end settlement schedule. Must run outside peak hours (ADR-11).'),
  ('logging.level.com.acmepay', 'payment-service', 'INFO', 'Application log level.');
