INSERT INTO incident (id, service_id, severity, started_at, resolved_at, symptom, root_cause, lesson, caused_by) VALUES
  ('INC-11', 'payment-service', 'SEV3', '2026-03-04 09:10:00', '2026-03-04 10:05:00', 'Gateway calls failed with SSLHandshakeException: PKIX path building failed.', 'The payment gateway rotated its TLS certificate chain and the client trust store was stale.', 'Subscribe to the gateway''s certificate rotation notices and automate trust store updates.', NULL),
  ('INC-13', 'payment-service', 'SEV3', '2026-03-07 14:10:00', '2026-03-07 15:00:00', 'Pods restarted with No space left on device. The log volume was full.', 'Debug logging left on in the refund module filled the node''s log volume.', 'Always set log rotation, and turn debug logging off after an investigation.', NULL),
  ('INC-15', 'payment-service', 'SEV2', '2026-03-10 11:20:00', '2026-03-10 13:45:00', 'Response times spiked to 8 seconds with long GC pauses. Heap usage climbed steadily.', 'A receipt cache had no size limit and grew until the heap was nearly full.', 'A bigger heap hides a leak. Every in-memory cache needs a size limit.', NULL),
  ('INC-18', 'payment-service', 'SEV2', '2026-03-12 09:40:00', '2026-03-12 11:05:00', 'Payment API requests timed out. Logs: HikariPool-1 - Connection is not available, request timed out after 30000ms.', 'DEP-2026-017 (v2.4.0) raised spring.datasource.hikari.maximum-pool-size from 20 to 50. 4 replicas x 50 = 200 connections, above MySQL max_connections of 150, so MySQL rejected connections with error 1040 Too many connections.', 'Replicas x maximum-pool-size must stay below MySQL max_connections.', 'DEP-2026-017'),
  ('INC-20', 'payment-service', 'SEV3', '2026-03-17 16:05:00', '2026-03-17 16:50:00', 'Tomcat thread pool exhausted. Requests queued while gateway calls were slow.', 'The payment gateway slowed down, and every request thread waited on it.', 'More threads don''t help when a downstream call is slow.', NULL),
  ('INC-22', 'payment-service', 'SEV3', '2026-03-20 10:30:00', '2026-03-20 11:10:00', 'NullPointerException in the refund path right after a deploy. Refunds failed.', 'A new optional field on refund requests was read without a null check.', 'Add a test for optional fields on every new request field.', NULL),
  ('INC-24', 'payment-service', 'SEV3', '2026-03-24 14:20:00', '2026-03-24 15:45:00', 'Gateway calls returned HTTP 504 and Tomcat request threads piled up during a payment provider outage.', 'Payment provider outage.', 'Check the provider status page before changing timeouts. Longer timeouts make an outage worse.', NULL),
  ('INC-26', 'payment-service', 'SEV3', '2026-03-27 13:15:00', '2026-03-27 14:30:00', 'Gateway webhooks were rejected with a signature mismatch.', 'The gateway rotated its webhook signing key, and the old key was still configured.', 'Track the gateway''s key rotation schedule, and accept both keys during a rotation.', NULL),
  ('INC-27', 'payment-service', 'SEV3', '2026-03-30 09:40:00', '2026-03-30 10:20:00', 'UnknownHostException for the gateway host from some pods.', 'A cluster DNS pod was overloaded and dropped lookups.', 'Watch DNS lookup errors, and size cluster DNS for peak traffic.', NULL),
  ('INC-29', 'payment-service', 'SEV1', '2026-04-02 13:05:00', '2026-04-02 15:30:00', 'Customers were charged twice. Gateway logs showed repeated charge requests for the same order.', 'DEP-2026-024 (v2.7.0) raised payment.retry.max-attempts from 3 to 5 while payment.retry.idempotency-enabled was false, so retries after gateway timeouts created duplicate charges.', 'Retries must be idempotent. Never raise retries without idempotency keys.', 'DEP-2026-024'),
  ('INC-30', 'payment-service', 'SEV3', '2026-04-21 18:05:00', '2026-04-21 18:55:00', 'The gateway returned HTTP 429 Too Many Requests at evening peak.', 'Traffic passed the rate limit in the gateway contract.', 'Know the gateway contract limits, and rate-limit on our side before reaching them.', NULL),
  ('INC-31', 'payment-service', 'SEV2', '2026-05-19 12:15:00', '2026-05-19 13:00:00', 'HikariPool-1 - Connection is not available, request timed out after 5000ms at peak traffic.', 'DEP-2026-035 (v2.9.0) lowered spring.datasource.hikari.connection-timeout from 30000 to 5000, too short for peak-time connection waits.', 'A restart does not fix connection pool configuration. Check recent pool setting changes first.', 'DEP-2026-035'),
  ('INC-32', 'payment-service', 'SEV3', '2026-07-14 01:40:00', '2026-07-14 03:10:00', 'Settlement ran for 90 minutes instead of 15. One query did a full table scan.', 'A new settlement query filtered on a column without an index.', 'Check the query plan for every new settlement query.', NULL),
  ('INC-33', 'payment-service', 'SEV2', '2026-08-31 23:40:00', '2026-09-01 01:10:00', 'MySQL error 1213 Deadlock found when trying to get lock during month-end settlement. Checkout latency spiked.', 'DEP-2026-055 (v3.2.0) moved payment.settlement.cron to 23:30, overlapping peak checkout traffic.', 'Settlement must run outside peak hours.', 'DEP-2026-055'),
  ('INC-34', 'payment-service', 'SEV3', '2026-09-15 12:30:00', '2026-09-15 15:00:00', 'Receipts showed amounts off by one unit for currencies with three decimal places.', 'Receipt formatting rounded every currency to two decimal places.', 'Never assume two decimal places. Use the currency''s own precision.', NULL);
INSERT INTO troubleshooting_attempt (incident_id, seq, action, outcome, note) VALUES
  ('INC-11', 1, 'Restarted payment-service pods', 'FAILED', 'Handshake errors continued'),
  ('INC-11', 2, 'Updated the trust store with the new certificate chain', 'RESOLVED', NULL),
  ('INC-13', 1, 'Deleted old log files by hand', 'PARTIAL', 'Disk filled again within an hour'),
  ('INC-13', 2, 'Turned the refund module back to INFO and set log rotation to 500 MB', 'RESOLVED', NULL),
  ('INC-15', 1, 'Increased the JVM heap from 2 GB to 3 GB', 'FAILED', 'Pauses returned after two hours'),
  ('INC-15', 2, 'Added a 10,000-entry limit to the receipt cache', 'RESOLVED', NULL),
  ('INC-18', 1, 'Restarted payment-service pods', 'FAILED', 'Timeouts returned within 10 minutes'),
  ('INC-18', 2, 'Raised the client timeout to 60s', 'PARTIAL', 'Fewer errors, root cause unchanged'),
  ('INC-18', 3, 'Reverted maximum-pool-size to 20', 'RESOLVED', NULL),
  ('INC-20', 1, 'Raised the Tomcat max threads from 200 to 400', 'PARTIAL', 'More memory use, same queueing'),
  ('INC-20', 2, 'Reverted the thread count and waited for the gateway to recover', 'RESOLVED', NULL),
  ('INC-22', 1, 'Rolled back to the previous version', 'RESOLVED', 'Fix shipped the next day'),
  ('INC-24', 1, 'Raised payment.gateway.timeout-ms from 8000 to 20000', 'PARTIAL', 'Threads piled up faster and more requests queued'),
  ('INC-24', 2, 'Reverted the timeout to 8000 and waited for the provider to recover', 'RESOLVED', 'Provider status page confirmed the outage'),
  ('INC-26', 1, 'Re-sent the failed webhooks from the gateway dashboard', 'FAILED', 'Signatures still failed'),
  ('INC-26', 2, 'Installed the new signing key from the gateway dashboard', 'RESOLVED', NULL),
  ('INC-27', 1, 'Scaled the cluster DNS deployment from 2 to 4 pods', 'RESOLVED', NULL),
  ('INC-29', 1, 'Lowered the gateway timeout to 5000', 'FAILED', 'Duplicate charges continued'),
  ('INC-29', 2, 'Reverted max-attempts to 3', 'RESOLVED', 'Duplicates stopped. Affected orders refunded'),
  ('INC-30', 1, 'Retried rejected calls sooner', 'FAILED', 'More 429s'),
  ('INC-30', 2, 'Asked the gateway for a higher limit and added client-side rate limiting', 'RESOLVED', NULL),
  ('INC-31', 1, 'Restarted payment-service pods', 'FAILED', 'Errors returned at the next traffic peak'),
  ('INC-31', 2, 'Reverted connection-timeout to 30000', 'RESOLVED', NULL),
  ('INC-32', 1, 'Re-ran the settlement batch', 'FAILED', 'Just as slow'),
  ('INC-32', 2, 'Added an index on payments.settled_on', 'RESOLVED', NULL),
  ('INC-33', 1, 'Restarted the settlement batch', 'FAILED', 'Deadlocks continued'),
  ('INC-33', 2, 'Moved the settlement cron back to 01:30', 'RESOLVED', NULL),
  ('INC-34', 1, 'Hotfixed the receipt template for one currency', 'PARTIAL', 'Other three-decimal currencies still wrong'),
  ('INC-34', 2, 'Used each currency''s own decimal places when formatting', 'RESOLVED', NULL);
INSERT INTO incident_key (incident_id, key_name) VALUES
  ('INC-18', 'spring.datasource.hikari.maximum-pool-size'),
  ('INC-24', 'payment.gateway.timeout-ms'),
  ('INC-29', 'payment.retry.max-attempts'),
  ('INC-29', 'payment.retry.idempotency-enabled'),
  ('INC-31', 'spring.datasource.hikari.connection-timeout'),
  ('INC-33', 'payment.settlement.cron');
INSERT INTO architecture_decision (id, service_id, key_name, decided_at, decision, reason, status, linked_incident_id) VALUES
  ('ADR-7', 'payment-service', 'spring.datasource.hikari.maximum-pool-size', '2026-03-15 11:00:00', 'Keep maximum-pool-size at 20 per replica.', 'After INC-18, replicas x pool size must stay below MySQL max_connections of 150, with headroom for ledger-service.', 'ACTIVE', 'INC-18'),
  ('ADR-12', 'payment-service', 'payment.gateway.timeout-ms', '2026-03-27 11:00:00', 'Keep payment.gateway.timeout-ms at 8000 and check the provider status page before changing it.', 'In INC-24 a longer timeout piled up threads during a provider outage.', 'ACTIVE', 'INC-24'),
  ('ADR-9', 'payment-service', 'payment.retry.max-attempts', '2026-04-06 11:00:00', 'Retries above 3 require payment.retry.idempotency-enabled to be true.', 'INC-29: retries without idempotency caused duplicate charges.', 'ACTIVE', 'INC-29'),
  ('ADR-10', 'payment-service', 'spring.datasource.hikari.connection-timeout', '2026-05-22 11:00:00', 'Keep connection-timeout at 30000 ms.', 'INC-31: 5000 ms caused connection errors at peak, and restarting did not help.', 'ACTIVE', 'INC-31'),
  ('ADR-11', 'payment-service', 'payment.settlement.cron', '2026-09-03 11:00:00', 'Settlement runs at 01:30 and never during peak hours.', 'INC-33: a 23:30 settlement overlapped peak traffic and caused deadlocks.', 'ACTIVE', 'INC-33');
INSERT INTO warning (id, deployment_id, key_name, created_at, kind, severity, summary, cited_refs, failed_attempts, prior_false_positive, recommendation, status, verdict_reason, decided_at) VALUES
  ('WARN-33', 'DEP-2026-025', 'payment.gateway.timeout-ms', '2026-04-05 17:05:00', 'DECISION_GUARD', 'SEV3', 'Changing payment.gateway.timeout-ms from 8000 to 10000 resembles INC-24, where a longer timeout piled up threads during a provider outage. ADR-12 governs this setting.', 'ADR-12,INC-24', NULL, NULL, 'Check the provider status page before changing the timeout.', 'FALSE_POSITIVE', 'Only the sandbox profile changes. Production stays at 8000.', '2026-04-05 19:05:00'),
  ('WARN-34', 'DEP-2026-027', 'spring.datasource.hikari.maximum-pool-size', '2026-04-14 06:11:00', 'DECISION_GUARD', 'SEV2', 'Raising spring.datasource.hikari.maximum-pool-size from 20 to 25 resembles INC-18: 4 replicas x 25 = 100 connections against MySQL max_connections of 150. ADR-7 governs this setting.', 'ADR-7,INC-18', 'Restarted payment-service pods (INC-18)', NULL, 'Keep the pool at 20 unless MySQL max_connections is raised first.', 'USEFUL', '4 x 25 = 100 leaves too little headroom for ledger-service. Change dropped.', '2026-04-14 08:11:00'),
  ('WARN-35', 'DEP-2026-028', 'payment.gateway.timeout-ms', '2026-04-18 12:43:00', 'DECISION_GUARD', 'SEV3', 'Changing payment.gateway.timeout-ms from 8000 to 9000 resembles INC-24, where a longer timeout piled up threads during a provider outage. ADR-12 governs this setting.', 'ADR-12,INC-24', NULL, NULL, 'Check the provider status page before changing the timeout.', 'FALSE_POSITIVE', 'Override applies to the refunds endpoint only, not charge calls.', '2026-04-18 14:43:00'),
  ('WARN-36', 'DEP-2026-029', 'payment.gateway.timeout-ms', '2026-04-22 19:16:00', 'DECISION_GUARD', 'SEV3', 'Changing payment.gateway.timeout-ms from 8000 to 8500 resembles INC-24, where a longer timeout piled up threads during a provider outage. ADR-12 governs this setting.', 'ADR-12,INC-24', NULL, NULL, 'Check the provider status page before changing the timeout.', 'FALSE_POSITIVE', 'Load-test profile only. Production unchanged.', '2026-04-22 21:16:00'),
  ('WARN-37', 'DEP-2026-032', 'payment.retry.idempotency-enabled', '2026-05-05 14:54:00', 'HISTORY', 'SEV1', 'Turning payment.retry.idempotency-enabled off resembles INC-29, where retries without idempotency caused duplicate charges.', 'INC-29', 'Lowered the gateway timeout to 5000 (INC-29)', NULL, 'Keep idempotency enabled.', 'USEFUL', 'Would have disabled idempotency. Reverted before shipping.', '2026-05-05 16:54:00'),
  ('WARN-38', 'DEP-2026-033', 'payment.gateway.timeout-ms', '2026-05-09 21:27:00', 'DECISION_GUARD', 'SEV3', 'Changing payment.gateway.timeout-ms from 8000 to 12000 resembles INC-24, where a longer timeout piled up threads during a provider outage. ADR-12 governs this setting.', 'ADR-12,INC-24', NULL, NULL, 'Check the provider status page before changing the timeout.', 'FALSE_POSITIVE', 'Staging only, for a provider sandbox that responds slowly.', '2026-05-09 23:27:00'),
  ('WARN-39', 'DEP-2026-037', 'spring.datasource.hikari.connection-timeout', '2026-05-28 02:33:00', 'DECISION_GUARD', 'SEV2', 'Lowering spring.datasource.hikari.connection-timeout from 30000 to 28000 resembles INC-31, where 5000 ms caused Connection is not available errors at peak. ADR-10 governs this setting.', 'ADR-10,INC-31', 'Restarted payment-service pods (INC-31)', NULL, 'Keep connection-timeout at 30000 ms.', 'FALSE_POSITIVE', 'Staging only. Production unchanged.', '2026-05-28 04:33:00'),
  ('WARN-40', 'DEP-2026-038', 'spring.datasource.hikari.connection-timeout', '2026-06-01 22:33:00', 'DECISION_GUARD', 'SEV2', 'Lowering spring.datasource.hikari.connection-timeout from 30000 to 10000 resembles INC-31, where 5000 ms caused Connection is not available errors at peak. ADR-10 governs this setting.', 'ADR-10,INC-31', 'Restarted payment-service pods (INC-31)', NULL, 'Keep connection-timeout at 30000 ms.', 'USEFUL', 'Too close to the INC-31 value. Kept at 30000.', '2026-06-02 00:33:00'),
  ('WARN-41', 'DEP-2026-039', 'spring.datasource.hikari.maximum-pool-size', '2026-06-06 18:33:00', 'DECISION_GUARD', 'SEV2', 'Raising spring.datasource.hikari.maximum-pool-size from 20 to 40 resembles INC-18: 4 replicas x 40 = 160 connections against MySQL max_connections of 150. ADR-7 governs this setting.', 'ADR-7,INC-18', 'Restarted payment-service pods (INC-18)', NULL, 'Keep the pool at 20 unless MySQL max_connections is raised first.', 'USEFUL', '4 x 40 = 160 would exceed 150. Change dropped.', '2026-06-06 20:33:00'),
  ('WARN-42', 'DEP-2026-041', 'payment.retry.max-attempts', '2026-06-16 10:33:00', 'DECISION_GUARD', 'SEV1', 'Changing payment.retry.max-attempts from 3 to 4 resembles INC-29, where extra retries caused duplicate charges. ADR-9 governs this setting.', 'ADR-9,INC-29', 'Lowered the gateway timeout to 5000 (INC-29)', NULL, 'Confirm idempotency is enabled before raising retries.', 'FALSE_POSITIVE', 'payment.retry.idempotency-enabled is true, so the INC-29 duplicate-charge risk did not apply.', '2026-06-16 12:33:00'),
  ('WARN-43', 'DEP-2026-044', 'payment.gateway.timeout-ms', '2026-07-02 01:58:00', 'DECISION_GUARD', 'SEV3', 'Changing payment.gateway.timeout-ms from 8000 to 15000 resembles INC-24, where a longer timeout piled up threads during a provider outage. ADR-12 governs this setting.', 'ADR-12,INC-24', NULL, NULL, 'Check the provider status page before changing the timeout.', 'USEFUL', 'Would pile up threads in a provider outage, as in INC-24. Kept at 8000.', '2026-07-02 03:58:00'),
  ('WARN-44', 'DEP-2026-046', 'spring.datasource.hikari.connection-timeout', '2026-07-12 12:15:00', 'DECISION_GUARD', 'SEV2', 'Lowering spring.datasource.hikari.connection-timeout from 30000 to 25000 resembles INC-31, where 5000 ms caused Connection is not available errors at peak. ADR-10 governs this setting.', 'ADR-10,INC-31', 'Restarted payment-service pods (INC-31)', NULL, 'Keep connection-timeout at 30000 ms.', 'FALSE_POSITIVE', 'Staging only, for a connection-leak test.', '2026-07-12 14:15:00'),
  ('WARN-45', 'DEP-2026-048', 'spring.datasource.hikari.maximum-pool-size', '2026-07-22 22:32:00', 'DECISION_GUARD', 'SEV2', 'Raising spring.datasource.hikari.maximum-pool-size from 20 to 30 resembles INC-18: 4 replicas x 30 = 120 connections against MySQL max_connections of 150. ADR-7 governs this setting.', 'ADR-7,INC-18', 'Restarted payment-service pods (INC-18)', NULL, 'Keep the pool at 20 unless MySQL max_connections is raised first.', 'USEFUL', '4 x 30 = 120 leaves too little headroom for ledger-service. Change dropped.', '2026-07-23 00:32:00'),
  ('WARN-46', 'DEP-2026-050', 'spring.datasource.hikari.connection-timeout', '2026-08-02 08:50:00', 'DECISION_GUARD', 'SEV2', 'Lowering spring.datasource.hikari.connection-timeout from 30000 to 8000 resembles INC-31, where 5000 ms caused Connection is not available errors at peak. ADR-10 governs this setting.', 'ADR-10,INC-31', 'Restarted payment-service pods (INC-31)', NULL, 'Keep connection-timeout at 30000 ms.', 'USEFUL', 'Would repeat INC-31. Kept at 30000.', '2026-08-02 10:50:00'),
  ('WARN-47', 'DEP-2026-051', 'payment.gateway.timeout-ms', '2026-08-07 13:58:00', 'DECISION_GUARD', 'SEV3', 'Changing payment.gateway.timeout-ms from 8000 to 20000 resembles INC-24, where a longer timeout piled up threads during a provider outage. ADR-12 governs this setting.', 'ADR-12,INC-24', NULL, NULL, 'Check the provider status page before changing the timeout.', 'USEFUL', 'The exact change that made INC-24 worse. Dropped.', '2026-08-07 15:58:00'),
  ('WARN-48', 'DEP-2026-052', 'payment.gateway.timeout-ms', '2026-08-12 19:07:00', 'DECISION_GUARD', 'SEV3', 'Changing payment.gateway.timeout-ms from 8000 to 8200 resembles INC-24, where a longer timeout piled up threads during a provider outage. ADR-12 governs this setting.', 'ADR-12,INC-24', NULL, NULL, 'Check the provider status page before changing the timeout.', 'FALSE_POSITIVE', 'Staging only, for the fraud-check latency budget.', '2026-08-12 21:07:00'),
  ('WARN-49', 'DEP-2026-053', 'payment.retry.idempotency-enabled', '2026-08-18 00:15:00', 'HISTORY', 'SEV1', 'Turning payment.retry.idempotency-enabled off resembles INC-29, where retries without idempotency caused duplicate charges.', 'INC-29', 'Lowered the gateway timeout to 5000 (INC-29)', NULL, 'Keep idempotency enabled.', 'USEFUL', 'Would reintroduce the INC-29 duplicate-charge risk. Reverted.', '2026-08-18 02:15:00'),
  ('WARN-50', 'DEP-2026-056', 'payment.settlement.cron', '2026-09-02 20:09:00', 'HISTORY', 'SEV2', 'Moving payment.settlement.cron to 0 0 22 * * * resembles INC-33, where settlement overlapped peak traffic and caused deadlocks.', 'INC-33', 'Restarted the settlement batch (INC-33)', NULL, 'Keep settlement outside peak hours.', 'USEFUL', '22:00 is peak checkout time. Kept at 01:30.', '2026-09-02 22:09:00'),
  ('WARN-51', 'DEP-2026-057', 'spring.datasource.hikari.maximum-pool-size', '2026-09-08 05:45:00', 'DECISION_GUARD', 'SEV2', 'Raising spring.datasource.hikari.maximum-pool-size from 20 to 50 resembles INC-18: 4 replicas x 50 = 200 connections against MySQL max_connections of 150. ADR-7 governs this setting.', 'ADR-7,INC-18', 'Restarted payment-service pods (INC-18)', NULL, 'Keep the pool at 20 unless MySQL max_connections is raised first.', 'USEFUL', 'The exact INC-18 change. Dropped.', '2026-09-08 07:45:00'),
  ('WARN-52', 'DEP-2026-058', 'payment.gateway.timeout-ms', '2026-09-13 15:21:00', 'DECISION_GUARD', 'SEV3', 'Changing payment.gateway.timeout-ms from 8000 to 6000 resembles INC-24, where a longer timeout piled up threads during a provider outage. ADR-12 governs this setting.', 'ADR-12,INC-24', NULL, NULL, 'Check the provider status page before changing the timeout.', 'FALSE_POSITIVE', 'Staging only. Production stays at 8000.', '2026-09-13 17:21:00'),
  ('WARN-53', 'DEP-2026-059', 'spring.datasource.hikari.connection-timeout', '2026-09-19 00:57:00', 'DECISION_GUARD', 'SEV2', 'Lowering spring.datasource.hikari.connection-timeout from 30000 to 5000 resembles INC-31, where 5000 ms caused Connection is not available errors at peak. ADR-10 governs this setting.', 'ADR-10,INC-31', 'Restarted payment-service pods (INC-31)', NULL, 'Keep connection-timeout at 30000 ms.', 'USEFUL', 'The exact INC-31 change. Dropped.', '2026-09-19 02:57:00'),
  ('WARN-54', 'DEP-2026-060', 'payment.settlement.cron', '2026-09-24 10:33:00', 'DECISION_GUARD', 'SEV2', 'Moving payment.settlement.cron to 0 30 23 * * * resembles INC-33, where settlement overlapped peak traffic and caused deadlocks. ADR-11 governs this setting.', 'ADR-11,INC-33', 'Restarted the settlement batch (INC-33)', NULL, 'Keep settlement outside peak hours.', 'USEFUL', 'The exact INC-33 change. Dropped.', '2026-09-24 12:33:00');
